/**
 * Descriptions for the Properties tables. Names, types, defaults and "required"
 * come from the components' TypeScript (src/lib/props-data.json, generated by
 * scripts/gen-props.mjs); this file only adds the human wording.
 * Lookup order: "Component.prop", then the shared wording for that prop name.
 */

